export function createChessScreen(container: HTMLElement): void {
  injectStyles();
  const engine = new ChessEngine();

  const root = document.createElement('div');
  root.className = 'vaca-chess';
  root.tabIndex = 0;

  const title = document.createElement('h2');
  title.textContent = '♞ 3D Chess ♞';

  const status = document.createElement('div');
  status.className = 'status';

  // ── Board (2D) ──
  const boardWrap = document.createElement('div');
  boardWrap.className = 'board-wrap';
  const boardEl = document.createElement('div');
  boardEl.className = 'board';

  // ── 3D canvas ──
  const canvas = document.createElement('canvas');
  canvas.width = 560;
  canvas.height = 420;
  canvas.style.display = 'none';

  // ── Controls ──
  const controls = document.createElement('div');
  controls.className = 'controls';
  const btnReset = document.createElement('button');
  btnReset.textContent = '⟲ Reset';
  const btnUndo = document.createElement('button');
  btnUndo.textContent = '↩ Undo';
  const btn3d = document.createElement('button');
  btn3d.textContent = '🎲 3D Board';
  controls.append(btnReset, btnUndo, btn3d);

  const moveLog = document.createElement('div');
  moveLog.className = 'movelog';
  moveLog.textContent = 'Move log:';

  root.append(title, status, boardWrap, canvas, controls, moveLog);
  container.appendChild(root);

  let selected: Square | null = null;
  let legal: Move[] = [];
  let threeD = false;

  function reRender(): void {
    status.textContent = engine.getStatusMessage();
    status.className = 'status' + (engine.getStatus() === 'check' ? ' check' : engine.getStatus() === 'checkmate' ? ' checkmate' : '');

    selected = engine.getSelected();
    legal = engine.getSelectedMoves();

    // Board
    boardEl.innerHTML = '';
    const board = engine.getBoard();
    const legalSet = new Set(legal.map(m => squareKey(m.to)));
    for (let r = 0; r < 8; r++) {
      for (let c = 0; c < 8; c++) {
        const sq = document.createElement('div');
        sq.className = 'sq ' + ((r + c) % 2 === 0 ? 'light' : 'dark');
        sq.dataset.row = String(r);
        sq.dataset.col = String(c);
        if (selected && selected.row === r && selected.col === c) sq.classList.add('selected');
        const piece = board[r][c];
        if (piece) {
          const span = document.createElement('span');
          span.className = 'piece ' + piece.color;
          span.textContent = GLYPHS[piece.color][piece.type];
          sq.appendChild(span);
        }
        if (legalSet.has(`${r},${c}`)) {
          sq.classList.add('hint');
          if (board[r][c]) sq.classList.add('capture');
        }
        boardEl.appendChild(sq);
      }
    }
    if (!boardWrap.contains(boardEl)) boardWrap.appendChild(boardEl);

    // Move log
    const history = engine.getHistory();
    const lines = history.map((m, i) => {
      const from = fileRank(m.from);
      const to = fileRank(m.to);
      const promo = m.promotion ? `=${m.promotion.toUpperCase()}` : '';
      const tag = m.castling ? (m.castling === 'k' ? ' O-O' : ' O-O-O') : m.enPassant ? ' e.p.' : '';
      return `${Math.floor(i / 2) + 1}.${i % 2 === 0 ? '' : '..'} ${from}${to}${promo}${tag}`;
    });
    moveLog.textContent = 'Move log: ' + (lines.length ? lines.join('  ') : '(no moves yet)');

    if (threeD) draw3D(canvas, board);
  }

  function draw3D(cv: HTMLCanvasElement, board: ReturnType<ChessEngine['getBoard']>): void {
    const ctx = cv.getContext('2d');
    if (!ctx) return;
    const w = cv.width;
    const h = cv.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, w, h);

    const cx = w / 2;
    const cy = h * 0.42;
    const F = 300; // focal length
    const zCam = 13; // camera distance along the row axis
    const TILT = 0.55; // vertical foreshortening

    // Project one square: near rows (large r) appear bigger and lower.
    for (let r = 0; r < 8; r++) {
      for (let c = 0; c < 8; c++) {
        const depth = zCam - (r - 3.5);
        const s = F / depth;
        const x = cx + (c - 3.5) * s;
        const y = cy + (r - 3.5) * s * TILT;
        const size = s * 0.92;
        ctx.fillStyle = (r + c) % 2 === 0 ? '#f0d9b5' : '#b58863';
        ctx.beginPath();
        ctx.rect(x - size / 2, y - size / 2, size, size);
        ctx.fill();
        ctx.strokeStyle = 'rgba(0,0,0,0.35)';
        ctx.lineWidth = 1;
        ctx.stroke();

        const piece = board[r][c];
        if (piece) {
          ctx.font = `${Math.round(size * 0.72)}px serif`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';
          ctx.fillStyle = piece.color === 'w' ? '#ffffff' : '#111111';
          ctx.shadowColor = 'rgba(0,0,0,0.6)';
          ctx.shadowBlur = 3;
          ctx.fillText(GLYPHS[piece.color][piece.type], x, y + size * 0.06);
          ctx.shadowBlur = 0;
        }
      }
    }
  }

  function fileRank(sq: Square): string {
    const files = 'abcdefgh';
    return files[sq.col] + (8 - sq.row);
  }

  // Wire inputs
  const input = new InputHandler(engine, reRender);
  input.attach(root);

  btnReset.addEventListener('click', () => {
    engine.reset();
    reRender();
  });
  btnUndo.addEventListener('click', () => {
    engine.undo();
    reRender();
  });
  btn3d.addEventListener('click', () => {
    threeD = !threeD;
    boardEl.style.display = threeD ? 'none' : 'grid';
    canvas.style.display = threeD ? 'block' : 'none';
    btn3d.textContent = threeD ? '📐 2D Board' : '🎲 3D Board';
    reRender();
  });

  reRender();
}

