    this.store.selected = from;
    return this.store.getLegalMoves(from);
  }

  /** Legal moves for the currently selected square (empty when none). */
  getSelectedMoves(): Move[] {
    const s = this.store.selected;
    return s ? this.store.getLegalMoves(s) : [];
  }

  getSelected(): Square | null {
    return this.store.selected;
  }

  clearSelection(): void {
    this.store.selected = null;
  }

  /** Try to play `from` -> `to`. Returns a user-facing result message. */
  move(from: Square, to: Square): { ok: boolean; message: string } {
    return this.store.tryMove(from, to);
  }

  undo(): boolean {
    return this.store.undo();
  }

